import numpy as np
import pandas as pd
from datetime import datetime, timedelta
import calendar

def r_time_add(time, periods=None, year=None, month=None, week=None, 
               day=None, hour=None, minute=None, second=None, 
               roll_month="preday", roll_dst="post", *args, **kwargs):

    # Handle ... dots (R's dots are passed as kwargs in Python)
    dots_dict = kwargs
    if dots_dict:
        clean_dots = {}
        for k, v in dots_dict.items():
            # R's sub("s$", "", names(dots))
            new_k = k[:-1] if k.endswith('s') else k
            clean_dots[new_k] = v

        if periods is None:
            periods = clean_dots
        elif isinstance(periods, dict):
            periods = periods.copy()
            for k, v in clean_dots.items():
                if k in periods:
                    periods[k] = periods[k] + v
                else:
                    periods[k] = v

    if time is None:
        return None

    # Handle input types (scalar vs array)
    is_scalar = not isinstance(time, (list, np.ndarray, pd.Series))
    if is_scalar:
        times = pd.to_datetime([time])
    else:
        times = pd.to_datetime(time)

    if len(times) == 0:
        return time if not is_scalar else None

    if periods is None:
        periods = {}
    elif not isinstance(periods, dict):
        # Matches "character periods are not implemented yet"
        raise TypeError("character periods are not implemented yet")

    prds_defaults = {'year': year, 'month': month, 'week': week, 'day': day, 
                     'hour': hour, 'minute': minute, 'second': second}

    final_periods = periods.copy()
    for nm, val in prds_defaults.items():
        if val is not None:
            if nm not in final_periods or final_periods[nm] is None:
                final_periods[nm] = val
            else:
                final_periods[nm] = final_periods[nm] + val

    def get_val(key, idx):
        val = final_periods.get(key, 0)
        if val is None: return 0
        if isinstance(val, (np.ndarray, list, pd.Series)):
            return val[idx]
        return val

    res_list = []
    for i in range(len(times)):
        ts = times[i]
        if pd.isna(ts):
            res_list.append(ts)
            continue

        # R's POSIXct is essentially UTC.
        # To perform calendar arithmetic, we use naive timestamps.
        if ts.tzinfo is not None:
            ts_naive = ts.tz_localize(None)
        else:
            ts_naive = ts

        y_add = get_val('year', i)
        m_add = get_val('month', i)

        if y_add == 0 and m_add == 0:
            res_naive = ts_naive
        else:
            # Calendar arithmetic for years and months
            total_months = ts_naive.month - 1 + m_add + (y_add * 12)
            target_year = (total_months // 12) + ts_naive.year
            target_month = (total_months % 12) + 1
            _, days_in_month = calendar.monthrange(target_year, target_month)

            if ts_naive.day <= days_in_month:
                res_naive = ts_naive.replace(year=target_year, month=target_month, day=ts_naive.day)
            else:
                preday_ts = ts_naive.replace(year=target_year, month=target_month, day=days_in_month)
                overflow = ts_naive.day - days_in_month
                if roll_month == "preday":
                    res_naive = preday_ts
                elif roll_month == "postday":
                    res_naive = preday_ts + pd.Timedelta(days=1)
                elif roll_month == "boundary":
                    res_naive = (preday_ts + pd.Timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
                elif roll_month == "full":
                    res_naive = preday_ts + pd.Timedelta(days=overflow)
                else:
                    res_naive = preday_ts

        # Add day, week, hour, minute, second as fixed durations
        d_add = get_val('day', i) + (get_val('week', i) * 7)
        h_add = get_val('hour', i)
        min_add = get_val('minute', i)
        sec_add = get_val('second', i)

        res_naive = res_naive + pd.Timedelta(days=d_add, hours=h_add, minutes=min_add, seconds=sec_add)

        res_list.append(res_naive)

    # Convert results back to the requested type
    if is_scalar:
        val = res_list[0]
        if pd.isna(val): return np.nan
        return val.to_pydatetime()

    return np.array(res_list)
